  const WING_NAMES = Object.keys(WINGS)
  /* How many radii an outline is kept as. Steep edges want a lot of them. */
  const SHAPE_WIDTH = 1024
  const CELLS = new Float32Array(WING_NAMES.flatMap((name) => [...WINGS[name].cells, 0, 0]))

